#!/usr/bin/env dotnet
#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count total Friday the 13ths in a full 400-year cycle.

// Find the earliest Friday the 13th
DateOnly earliest = default;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
                earliest = d;
            break;
        }
    }
    if (earliest != default && earliest.Year < year)
        break;
}

Console.WriteLine($"Earliest Friday the 13th (from 0001-01-01): {earliest:yyyy-MM-dd}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine();

// Bonus: distribution by month
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}

Console.WriteLine("Distribution by month:");
for (int m = 0; m < 12; m++)
{
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");
}

